INSERT rules.Role (RoleCode, Name, Department, Description, CreatedBy)
SELECT v.c, v.n, v.d, v.x, N'SI2 library'
FROM (VALUES
    (N'CEO', N'Chief Executive Officer', N'Executive', N'Company results, appetite and guardrails.'),
    (N'CFO', N'Chief Financial Officer', N'Executive', N'Profitability, expenses, capital and reserves.'),
    (N'CUO', N'Chief Underwriting Officer', N'Underwriting', N'Underwriting appetite, authority and rate adequacy.'),
    (N'UNDERWRITER', N'Underwriter', N'Underwriting', N'Eligibility, referral and pricing decisions on individual risks.'),
    (N'SR_UNDERWRITER', N'Senior Underwriter', N'Underwriting', N'Referrals above an underwriter''s authority.'),
    (N'PRICING', N'Pricing Actuary', N'Actuarial', N'Rating factors, credits, surcharges and rate changes.'),
    (N'PRODUCT', N'Product Manager', N'Product', N'Products, coverages, forms and availability by state.'),
    (N'COMPLIANCE', N'Compliance Officer', N'Legal & Compliance', N'State requirements, notices and prohibited practices.'),
    (N'BILLING', N'Billing Specialist', N'Operations', N'Payment plans, past-due handling and cancellations for non-payment.'),
    (N'CLAIMS_ADJUSTER', N'Claims Adjuster', N'Claims', N'Triage, coverage, reserves and payments within authority.'),
    (N'CLAIMS_MANAGER', N'Claims Manager', N'Claims', N'Large losses, litigation and approvals above adjuster authority.'),
    (N'SIU', N'SIU Investigator', N'Claims', N'Suspected fraud referrals and investigations.'),
    (N'DISTRIBUTION', N'Distribution Manager', N'Distribution', N'Producer eligibility, appointments and commissions.'),
    (N'REINSURANCE', N'Reinsurance Manager', N'Finance', N'Facultative referrals and treaty limits.'),
    (N'ERM', N'Chief Risk Officer', N'Risk', N'Capital, catastrophe exposure and solvency.'),
    (N'DATA_STEWARD', N'Data Steward', N'Data', N'Data quality checks on every load.')
) v (c, n, d, x)
WHERE NOT EXISTS (SELECT 1 FROM rules.Role r WHERE r.RoleCode = v.c);

