JOIN rules.RuleSet rs ON rs.RuleSetCode = v.rs AND rs.ScopeId = 1
WHERE NOT EXISTS (SELECT 1 FROM rules.BusinessRule x WHERE x.RuleCode = v.c AND x.ScopeId = 1);

