INSERT rules.DecisionTable (TableCode, Name, OwnerRole, Description, InputsJson, OutputsJson, IsIllustrative, CreatedBy)
SELECT v.c, v.n, v.r, v.d, v.i, v.o, v.il, N'SI2 library'
FROM (VALUES
    (N'CANCEL_NOTICE_DAYS', N'Cancellation notice days by state and reason', N'COMPLIANCE', N'Minimum days of notice before a cancellation takes effect. Illustrative values: confirm each state with compliance.', N'["STATE", "CANCEL_REASON"]', N'["NOTICE_DAYS"]', 1),
    (N'MIN_PREMIUM', N'Minimum premium by line and product', N'PRICING', N'The lowest premium written for a policy term.', N'["LOB", "PRODUCT"]', N'["MIN_PREMIUM"]', 1),
    (N'COMMISSION_RATE', N'Agent commission by line and transaction', N'DISTRIBUTION', N'Commission paid to the producer as a share of premium.', N'["LOB", "TRANSACTION_TYPE"]', N'["COMMISSION_RATE"]', 1)
) v (c, n, r, d, i, o, il)
WHERE NOT EXISTS (SELECT 1 FROM rules.DecisionTable x WHERE x.TableCode = v.c);

