INSERT rules.RoleAuthority (RoleCode, AuthorityType, LobScope, LimitAmount, Notes, CreatedBy)
SELECT v.r, v.t, v.l, v.lim, v.n, N'SI2 library'
FROM (VALUES
    (N'UNDERWRITER', N'BIND_TIV', N'*', 2000000, N'Total insured value an underwriter may bind'),
    (N'SR_UNDERWRITER', N'BIND_TIV', N'*', 10000000, NULL),
    (N'CUO', N'BIND_TIV', N'*', 50000000, NULL),
    (N'UNDERWRITER', N'BIND_TIV', N'HO', 1000000, N'Coverage A'),
    (N'SR_UNDERWRITER', N'BIND_TIV', N'HO', 3000000, N'Coverage A'),
    (N'UNDERWRITER', N'RATE_DEVIATION_PCT', N'*', 10, N'Schedule rating up or down'),
    (N'SR_UNDERWRITER', N'RATE_DEVIATION_PCT', N'*', 25, NULL),
    (N'CLAIMS_ADJUSTER', N'RESERVE_CHANGE', N'*', 25000, NULL),
    (N'CLAIMS_MANAGER', N'RESERVE_CHANGE', N'*', 250000, NULL),
    (N'CLAIMS_ADJUSTER', N'CLAIM_PAYMENT', N'*', 25000, NULL),
    (N'CLAIMS_MANAGER', N'CLAIM_PAYMENT', N'*', 250000, NULL),
    (N'CFO', N'CLAIM_PAYMENT', N'*', 5000000, NULL),
    (N'BILLING', N'REFUND', N'*', 5000, NULL)
) v (r, t, l, lim, n)
WHERE NOT EXISTS (SELECT 1 FROM rules.RoleAuthority x WHERE x.RoleCode = v.r AND x.AuthorityType = v.t AND x.LobScope = v.l);

-- Seed rules written before the engine: give them an owner role, a phase and a scope from their line / state columns
UPDATE r SET OwnerRole = N'UNDERWRITER', Phase = CASE r.ActionType WHEN 'DECLINE' THEN N'ELIGIBILITY' WHEN 'REFER' THEN N'REFERRAL' WHEN 'SURCHARGE_PCT' THEN N'RATING' WHEN 'CREDIT_PCT' THEN N'RATING' WHEN 'ROUTE' THEN N'ROUTING' WHEN 'WARN' THEN N'ALERT' WHEN 'ACCEPT' THEN N'ELIGIBILITY' ELSE N'REFERRAL' END FROM rules.BusinessRule r JOIN rules.RuleSet s ON s.RuleSetId = r.RuleSetId
WHERE s.RuleSetCode = N'UW_PERSONAL_AUTO' AND r.Phase IS NULL;
UPDATE r SET OwnerRole = N'CUO', Phase = N'AUTHORITY' FROM rules.BusinessRule r JOIN rules.RuleSet s ON s.RuleSetId = r.RuleSetId
WHERE s.RuleSetCode = N'ROLE_AUTHORITY' AND r.Phase IS NULL;
UPDATE r SET OwnerRole = N'CLAIMS_ADJUSTER', Phase = N'ROUTING' FROM rules.BusinessRule r JOIN rules.RuleSet s ON s.RuleSetId = r.RuleSetId
WHERE s.RuleSetCode = N'CLAIMS_TRIAGE' AND r.Phase IS NULL;
UPDATE r SET OwnerRole = N'DATA_STEWARD', Phase = N'DATA' FROM rules.BusinessRule r JOIN rules.RuleSet s ON s.RuleSetId = r.RuleSetId
WHERE s.RuleSetCode = N'DATA_QUALITY' AND r.Phase IS NULL;
UPDATE r SET OwnerRole = N'DATA_STEWARD', Phase = N'DATA' FROM rules.BusinessRule r JOIN rules.RuleSet s ON s.RuleSetId = r.RuleSetId
WHERE s.RuleSetCode = N'ISO_BUREAU' AND r.Phase IS NULL;
UPDATE r SET OwnerRole = N'DATA_STEWARD', Phase = N'DATA' FROM rules.BusinessRule r JOIN rules.RuleSet s ON s.RuleSetId = r.RuleSetId
WHERE s.RuleSetCode = N'NCCI_EDITS' AND r.Phase IS NULL;
INSERT rules.RuleScope (RuleId, Dimension, ScopeValue, CreatedBy)
SELECT r.RuleId, 'LOB', LTRIM(RTRIM(x.value)), N'SI2 library' FROM rules.BusinessRule r CROSS APPLY STRING_SPLIT(r.LobScope, ',') x
WHERE r.LobScope <> '*' AND LTRIM(RTRIM(x.value)) <> '' AND NOT EXISTS (SELECT 1 FROM rules.RuleScope s WHERE s.RuleId = r.RuleId AND s.Dimension = 'LOB');
INSERT rules.RuleScope (RuleId, Dimension, ScopeValue, CreatedBy)
SELECT r.RuleId, 'STATE', LTRIM(RTRIM(x.value)), N'SI2 library' FROM rules.BusinessRule r CROSS APPLY STRING_SPLIT(r.StateScope, ',') x
WHERE r.StateScope <> '*' AND LTRIM(RTRIM(x.value)) <> '' AND NOT EXISTS (SELECT 1 FROM rules.RuleScope s WHERE s.RuleId = r.RuleId AND s.Dimension = 'STATE');
GO
SELECT (SELECT COUNT(*) FROM rules.Role) AS Roles, (SELECT COUNT(*) FROM rules.RuleTemplate) AS Templates,
       (SELECT COUNT(*) FROM rules.BusinessRule WHERE Status = 'ACTIVE') AS Rules, (SELECT COUNT(*) FROM rules.RuleScope) AS ScopeRows,
       (SELECT COUNT(*) FROM rules.DecisionTableRow) AS TableRows, (SELECT COUNT(*) FROM rules.RoleAuthority) AS AuthorityRows;
GO
